#include <bits/stdc++.h>
using namespace std;const int N=11;int p[N],h[N],e[3][N],n;bool v[N];long long P=998244853,M=P-1,r[3],o[3],d[3];long long z(long long x){x%=M;return x<0?x+M:x;}long long s(long long x){long long a=x,b=x+1;if(a&1)b/=2;else a/=2;return a%M*(b%M)%M;}long long E(int q,int a,int b,int c){long long x=0,y=0,u=0,w=0,t=q,L=max(a,max(b,c));while(t<=L){long long A=a/t,B=b/t,C=c/t;x=(x+A)%M;y=(y+B)%M;u=(u+A*B)%M;w=(w+A*C)%M;if(t>L/q)break;t*=q;}return z(b%M*(c%M)%M*x+a%M*(c%M)%M*y-c%M*u-b%M*w);}long long F(int q,int a,int b,int c){long long x=0,y=0,u=0,w=0,t=q,L=max(a,max(b,c));while(t<=L){long long A=t%M*s(a/t)%M,B=t%M*s(b/t)%M,C=t%M*s(c/t)%M;x=(x+A)%M;y=(y+B)%M;u=(u+A*B)%M;w=(w+A*C)%M;if(t>L/q)break;t*=q;}return z(s(b)*s(c)%M*x+s(a)*s(c)%M*y-s(c)*u-s(b)*w);}long long k(long long a,long long b){long long r=1;for(;b;b>>=1,a=a*a%P)if(b&1)r=r*a%P;return r;}void q(int a,int b,int c,long long*f){int L=max(a,b);for(int i=0;i<n&&p[i]<=L;i++)e[0][i]=E(p[i],a,b,c),e[1][i]=F(p[i],a,b,c),e[2][i]=0;for(int d=1;d<=min(a,min(b,c));d++)for(int i=0;i<n&&p[i]<=max(a/d,b/d);i++)e[2][i]=(e[2][i]+h[d]*E(p[i],a/d,b/d,c/d))%M;for(int t=0;t<3;t++)f[t]=1;for(int i=0;i<n&&p[i]<=L;i++)for(int t=0;t<3;t++)f[t]=f[t]*k(p[i],e[t][i])%P;}int main(int C,char**w){ios::sync_with_stdio(0);cin.tie(0);int R=C>1?stoi(w[1]):1000;unsigned long long x=C>2?stoull(w[2]):1;mt19937_64 g(x);h[1]=1;for(int i=2;i<N;i++){if(!v[i])p[n++]=i,h[i]=i-1;for(int j=0;j<n&&i*p[j]<N;j++){v[i*p[j]]=1;if(i%p[j]==0){h[i*p[j]]=h[i]*p[j];break;}h[i*p[j]]=h[i]*(p[j]-1);}}while(R--){int a=g()%6+1,b=g()%6+1,c=g()%6+1;for(int t=0;t<3;t++)o[t]=1;q(a,b,c,r);for(int i=1;i<=a;i++)for(int j=1;j<=b;j++)for(int l=1;l<=c;l++){long long y=1LL*i/__gcd(i,j)*j/__gcd(i,l);d[0]=1;d[1]=1LL*i*j*l;d[2]=__gcd(__gcd(i,j),l);for(int t=0;t<3;t++)o[t]=o[t]*k(y,d[t])%P;}for(int t=0;t<3;t++)if(r[t]!=o[t])return cout<<"WA\n",1;}cout<<"OK\n";}
